\begin{definition}
\label{topping-ch9-convex-parallel-function}
\source{topping:page-0112}
\dcref{ch9:5.3}
\group{curvature-pinching}
A parallel function \(\Psi:W\to\mathbb R\) is convex when its restriction
to each fibre \(W_p\) is convex.
\end{definition}

